package net.officefloor.hq.app.claim;

/**
 * A claim's status: DRAFT when added; opened (OPEN), then settled (SETTLED); a DRAFT or OPEN claim
 * can be voided (VOID). A SETTLED or VOID claim cannot change status.
 */
public enum ClaimStatus {
    DRAFT, OPEN, SETTLED, VOID;

    /** Whether a claim in this status may move to the given one. */
    public boolean canBecome(ClaimStatus next) {
        return switch (next) {
            case OPEN -> this == DRAFT;
            case SETTLED -> this == OPEN;
            case VOID -> this == DRAFT || this == OPEN;
            case DRAFT -> false;
        };
    }

    /** Whether a claim in this status counts toward the totals: only OPEN and SETTLED do. */
    public boolean counts() {
        return this == OPEN || this == SETTLED;
    }
}
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * Statements on a sheet. Taking a person's statement records their due-total at that moment, taken
 * on the sheet's today, and binds every claim of theirs that counts (OPEN or SETTLED) to the figure
 * it has then; a claim of theirs that does not count is unbound, so its figure is live again.
 */
@Service
public class StatementService {

    /** A person's statements: how many, and the last one (none before the first). */
    public record Summary(long personId, int count, Statement last) {
    }

    /** A statement just taken, with the person's claims as it left them. */
    public record Taken(Summary summary, List<Claim> claims) {
    }

    private final StatementRepository statements;
    private final PersonRepository people;
    private final ClaimRepository claims;
    private final ClaimService claimService;
    private final RateRepository rates;
    private final SheetService sheets;
    private final Audit audit;
    private final RollupService rollup;

    public StatementService(StatementRepository statements, PersonRepository people, ClaimRepository claims,
            ClaimService claimService, RateRepository rates, SheetService sheets, Audit audit, RollupService rollup) {
        this.rollup = rollup;
        this.statements = statements;
        this.people = people;
        this.claims = claims;
        this.claimService = claimService;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** Each person's statements on the sheet who has taken any. */
    @Transactional(readOnly = true)
    public List<Summary> list(String sheetId) {
        Map<Long, Summary> by = new LinkedHashMap<>();
        for (Statement s : statements.findBySheetIdOrderByIdAsc(sheetId)) {
            Summary was = by.get(s.getPersonId());
            by.put(s.getPersonId(), new Summary(s.getPersonId(), was == null ? 1 : was.count() + 1, s));
        }
        return List.copyOf(by.values());
    }

    @Transactional
    public Taken take(String sheetId, String user, long personId) {
        Person person = people.lockByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
        LocalDate today = sheets.today(sheetId);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId);
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean anyFigure = false;
        int counted = 0;
        for (Claim claim : theirs) {
            if (claim.getStatus().counts()) {
                BigDecimal figure = claimService.figure(sheetId, person, claim);
                claim.bind(true, figure);
                if (figure != null) {
                    total = total.add(figure);
                    anyFigure = true;
                }
                counted++;
            } else {
                claim.bind(false, null);
            }
        }
        claims.saveAllAndFlush(theirs);
        // as on screen: n/a when the grade has no rate today and no claim that counts has a figure
        BigDecimal dueTotal = anyFigure || rates.findInForce(sheetId, person.getGrade(), today).isPresent() ? total
                : null;
        Statement taken = statements.saveAndFlush(new Statement(sheetId, personId, today, dueTotal, counted));
        int count = (int) statements.findBySheetIdOrderByIdAsc(sheetId).stream()
                .filter(s -> Objects.equals(s.getPersonId(), personId)).count();
        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " due-total=" + money(dueTotal) + " claims=" + counted);
        rollup.recordChanges(sheetId, user, before);
        return new Taken(new Summary(personId, count, taken), theirs);
    }

    public static String money(BigDecimal value) {
        return value == null ? "n/a" : value.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
    }
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.util.List;
import java.math.BigDecimal;
import java.math.RoundingMode;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * The sheet's periods: added on the screen, each a name unique on the sheet (without regard to
 * case) and a from and to date, both inclusive; no two periods on a sheet overlap. A period can be
 * closed once: closing fixes its due-total at that moment, and no claim dated inside a closed
 * period can be added, edited, opened, settled or voided.
 */
@Service
public class PeriodService {

    private final PeriodRepository periods;
    private final SheetService sheets;
    private final SheetRepository sheetRows;
    private final Audit audit;
    private final RollupService rollup;

    public PeriodService(PeriodRepository periods, SheetService sheets, SheetRepository sheetRows, Audit audit,
            RollupService rollup) {
        this.rollup = rollup;
        this.periods = periods;
        this.sheets = sheets;
        this.sheetRows = sheetRows;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<Period> list(String sheetId) {
        return periods.findBySheetIdOrderByFromDateAsc(sheetId);
    }

    @Transactional
    public Period add(String sheetId, String user, String name, LocalDate from, LocalDate to) {
        if (to.isBefore(from)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A period's to-date cannot be before its from-date.");
        }
        sheets.load(sheetId, user);
        // hold the sheet so two periods added at the same moment are checked one after the other
        sheetRows.findLockedById(sheetId);
        if (periods.existsBySheetIdAndNameIgnoreCase(sheetId, name)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period name is already in use on this sheet.");
        }
        if (periods.existsBySheetIdAndFromDateLessThanEqualAndToDateGreaterThanEqual(sheetId, to, from)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period overlaps another.");
        }
        Period added;
        try {
            added = periods.saveAndFlush(new Period(sheetId, name, from, to));
        } catch (DataIntegrityViolationException e) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period name is already in use on this sheet.");
        }
        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + added.getName() + " from="
                + added.getFromDate() + " to=" + added.getToDate());
        return added;
    }

    /** Close a period, fixing its due-total now; refused (409) when it is already closed. */
    @Transactional
    public Period close(String sheetId, String user, long id) {
        // hold the sheet so no claim changes while the period's due-total is fixed
        sheetRows.findLockedById(sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet."));
        Period period = periods.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet."));
        if (period.isClosed()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is already closed.");
        }
        BigDecimal due = rollup.dueBetween(sheetId, period.getFromDate(), period.getToDate());
        period.close(due);
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_CLOSED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
                + " total=" + due.setScale(2, RoundingMode.UNNECESSARY).toPlainString());
        return saved;
    }

    /**
     * Refuse (423) a change to a claim dated inside a closed period. Holds the sheet first, so a
     * period cannot close while the change is under way.
     */
    public void refuseIfClosed(String sheetId, LocalDate date) {
        sheetRows.findLockedById(sheetId);
        if (periods.existsBySheetIdAndClosedTrueAndFromDateLessThanEqualAndToDateGreaterThanEqual(sheetId, date,
                date)) {
            throw new ResponseStatusException(HttpStatus.LOCKED, "That claim's date is inside a closed period.");
        }
    }
}
